export const RESPONSIBLE_INNOVATION_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu inovasi",q:"'Inovasi' paling tepat berarti...",options:["Ide atau cara baru yang benar-benar memberi manfaat & dipakai orang, bukan sekadar 'sesuatu yang baru'","Apa pun yang belum pernah ada sebelumnya, tidak peduli apakah berguna atau sama sekali tidak berguna","Menyalin ide orang lain lalu memberinya nama baru supaya kelihatan seperti buatan sendiri"],answer:0,explain:"Sesuatu yang baru tapi tidak berguna atau tidak dipakai bukan inovasi, itu hanya kebaruan. Inovasi = baru + bernilai + dipakai.",hint:"Baru + bermanfaat + dipakai, atau sekadar baru?"},
{n:2,type:"mcq",micro:"Inovasi vs sekadar canggih",q:"Sebuah alat baru penuh fitur canggih tapi membingungkan & tidak menyelesaikan masalah nyata. Ini...",options:["Inovasi terbaik","Belum tentu inovasi, kebaruan teknologi tidak sama dengan manfaat bagi orang","Pasti inovasi karena canggih"],answer:1,explain:"Inovasi dinilai dari nilai yang diberikan ke orang, bukan dari seberapa canggih atau barunya teknologinya.",hint:"Dinilai dari manfaat, atau dari kecanggihan?"},
{n:3,type:"mcq",micro:"Manfaat nyata",q:"Cara memastikan sebuah ide baru benar-benar bermanfaat:",options:["Cukup yakin sendiri bahwa ide itu bagus karena kita sudah memikirkannya dengan sangat matang dan lama","Lihat saja apakah idenya terlihat mengesankan & membuat orang yang melihatnya langsung berdecak kagum","Cek apakah ia menyelesaikan masalah nyata bagi orang tertentu & mereka benar-benar terbantu olehnya"],answer:2,explain:"Manfaat nyata bisa ditunjukkan: 'sebelumnya butuh X, sekarang lebih mudah/aman/murah bagi orang Y'.",hint:"Menyelesaikan masalah nyata orang, atau terlihat mengesankan?"},
{n:4,type:"mcq",micro:"Untuk siapa",q:"Pertanyaan pertama sebelum mengembangkan sebuah inovasi:",options:["'Siapa yang akan terbantu, & apakah masalah ini benar-benar penting bagi mereka?'","'Bagaimana caranya supaya inovasi ini cepat jadi terkenal dan dibicarakan banyak orang di mana-mana?'","'Teknologi paling keren apa yang bisa kupakai supaya hasilnya terlihat canggih dan sangat modern?'"],answer:0,explain:"Inovasi yang bermanfaat dimulai dari orang & kebutuhan nyata, bukan dari teknologi atau keinginan terkenal.",hint:"Siapa yang terbantu & apakah penting, atau bagaimana jadi terkenal?"},
{n:5,type:"mcq",micro:"Inovasi kecil juga berharga",q:"Manakah yang bisa disebut inovasi?",options:["Hanya hal yang melibatkan komputer atau mesin canggih yang bisa disebut sebagai sebuah inovasi","Cara sederhana menyusun antrean sehingga lebih adil & cepat, yang kemudian dipakai terus","Hanya penemuan besar yang mengubah dunia seperti listrik & pesawat terbang yang pantas disebut inovasi"],answer:1,explain:"Inovasi tidak harus besar. Perbaikan kecil yang nyata & bertahan pada cara sesuatu dilakukan tetap inovasi.",hint:"Termasuk perbaikan kecil yang nyata, atau hanya penemuan besar?"},
{n:6,type:"mcq",micro:"Bertanggung jawab",q:"'Inovasi yang bertanggung jawab' berarti...",options:["Membuat sesuatu secepat mungkin supaya bisa segera dipakai orang sebelum pesaing membuat yang serupa","Mengabaikan kemungkinan dampak buruk karena dampak itu belum tentu terjadi dan hanya membuat ragu","Memikirkan dampak sesuatu pada semua orang & lingkungan, bukan hanya manfaat bagi penggunanya atau pembuatnya"],answer:2,explain:"Setiap inovasi punya dampak yang lebih luas dari yang dituju. Bertanggung jawab = memikirkan & mengelola dampak itu sejak awal.",hint:"Memikirkan dampak luas, atau hanya manfaat bagi pengguna?"},
{n:7,type:"mcq",micro:"Dampak tak terduga",q:"Kenapa inovasi perlu dipikirkan dampak sampingannya?",options:["Sesuatu yang membantu satu hal kadang menimbulkan masalah baru di tempat lain yang tak terduga","Dampak samping tidak pernah ada, sebab inovasi yang baik pasti hanya membawa kebaikan bagi semua","Itu hanya menghambat kemajuan sehingga sebaiknya tidak perlu dipikirkan oleh para pembuat inovasi"],answer:0,explain:"Contoh: kantong plastik memecahkan masalah membawa barang, lalu menciptakan masalah sampah besar. Memikirkan ini lebih awal membantu.",hint:"Bisa menimbulkan masalah baru, atau tidak pernah ada dampak samping?"},
{n:8,type:"mcq",micro:"Siapa yang terdampak",q:"Selain orang yang memakai sebuah inovasi, siapa lagi yang bisa terpengaruh?",options:["Hanya pembuatnya","Orang di sekitar, orang yang tidak memakainya, pekerja yang membuatnya, lingkungan, & generasi mendatang","Tidak ada, hanya penggunanya"],answer:1,explain:"Dampak menyebar. Inovasi yang bertanggung jawab memetakan semua pihak yang tersentuh, bukan hanya pengguna langsung.",hint:"Banyak pihak & lingkungan, atau hanya pengguna?"},
{n:9,type:"order",micro:"Menilai sebuah ide inovasi",q:"Urutkan langkah menilai apakah sebuah ide baru layak dikembangkan.",items:["Perjelas: masalah apa yang dipecahkan & untuk siapa","Cek apakah masalah itu nyata & penting bagi mereka","Pikirkan siapa lagi yang terdampak & bagaimana (baik & buruk)","Putuskan: lanjut, perbaiki agar dampak buruknya kecil, atau tidak"],answer:[0,1,2,3],explain:"Perjelas → cek pentingnya → petakan dampak → putuskan. Memikirkan dampak sebelum membangun, bukan sesudah.",hint:"Memikirkan dampak pada pihak lain sebelum atau sesudah memutuskan lanjut?"},
{n:10,type:"mcq",micro:"Kebaruan bukan tujuan",q:"'Yang penting berbeda dari yang sudah ada' sebagai satu-satunya tujuan berbahaya karena...",options:["Selalu menghasilkan hal yang hebat karena sesuatu yang berbeda pasti lebih menarik daripada yang lama","Tidak mungkin berbahaya, sebab berbeda dari yang sudah ada selalu berarti lebih baik dari yang lama","Bisa menghasilkan sesuatu yang berbeda tapi lebih buruk atau tidak berguna"],answer:2,explain:"Perubahan demi perubahan bukan inovasi. Inovasi mengubah sesuatu MENJADI LEBIH BAIK untuk orang yang dituju.",hint:"Berbeda bisa lebih buruk, atau berbeda selalu lebih baik?"},
{n:11,type:"tf",micro:"Inovasi butuh dipakai",q:"Benar atau Salah: Sebuah ide baru yang brilian tapi tidak pernah dipakai siapa pun belum bisa disebut inovasi.",answer:true,explain:"Inovasi terjadi ketika sesuatu yang baru benar-benar diadopsi & memberi nilai. Ide di laci belum menjadi inovasi.",hint:"Perlu dipakai & memberi nilai, atau cukup ide brilian?"},
{n:12,type:"tf",micro:"Semua inovasi selalu baik?",q:"Benar atau Salah: Semua inovasi otomatis baik untuk masyarakat karena artinya kemajuan.",answer:false,explain:"Sebaliknya, inovasi bisa merugikan: mesin yang membuat banyak orang kehilangan pekerjaan tanpa persiapan, produk yang membuat kecanduan, senjata yang lebih mematikan. 'Baru' & 'maju' tidak sama dengan 'baik'.",hint:"Otomatis baik, atau bisa merugikan juga?"},
{n:13,type:"mcq",micro:"Manfaat & biaya",q:"Menilai inovasi secara jujur berarti melihat...",options:["Manfaatnya DAN biayanya (uang, waktu, dampak sosial, dampak lingkungan), lalu menimbang","Hanya manfaatnya","Hanya kekurangannya"],answer:0,explain:"Setiap inovasi menukar sesuatu. Melihat kedua sisi membuat kita bisa memutuskan apakah pertukarannya sepadan.",hint:"Manfaat & biaya keduanya, atau satu sisi saja?"},
{n:14,type:"mcq",micro:"Inovasi & kebutuhan vs keinginan",q:"Inovasi yang paling bernilai biasanya menjawab...",options:["Keinginan pembuatnya sendiri supaya ia merasa puas dan dikenal luas oleh banyak orang di sekitarnya","Kebutuhan penting yang selama ini sulit dipenuhi, bukan sekadar menambah kenyamanan kecil yang sudah cukup","Keinginan sepele yang mudah dipenuhi dengan cara lain yang sudah ada dan murah dikerjakan siapa pun"],answer:1,explain:"Menyelesaikan masalah air bersih lebih bernilai daripada membuat versi ke-20 dari mainan yang sudah ada. Fokus pada kebutuhan penting.",hint:"Kebutuhan penting yang sulit dipenuhi, atau kenyamanan kecil?"},
{n:15,type:"mcq",micro:"Jujur soal manfaat",q:"Saat memperkenalkan inovasi, kejujuran berarti...",options:["Melebih-lebihkan manfaatnya agar orang lebih tertarik dan mau segera mencoba atau membelinya","Menyembunyikan kekurangannya supaya orang tidak ragu dan inovasinya lebih cepat diterima banyak orang","Menyampaikan manfaatnya dengan akurat, termasuk batasannya & apa yang belum bisa dilakukannya"],answer:2,explain:"Klaim berlebihan merugikan pengguna yang kecewa & merusak kepercayaan. Inovasi yang bertanggung jawab jujur tentang apa yang bisa & tidak bisa.",hint:"Akurat termasuk batasan, atau dilebih-lebihkan?"},
{n:16,type:"tf",micro:"Memikirkan dampak sejak awal",q:"Benar atau Salah: Memikirkan kemungkinan dampak buruk sebuah inovasi paling baik ditunda sampai setelah ia dibuat & dipakai luas, supaya tidak menghambat ide.",answer:false,explain:"Sebaliknya, setelah sesuatu tersebar luas, memperbaiki dampak buruknya jauh lebih sulit & mahal. Memikirkannya sejak tahap ide membuka pilihan untuk merancang lebih baik.",hint:"Sejak tahap ide, atau setelah terlanjur tersebar?"},
{n:17,type:"mcq",micro:"Inovasi & orang yang tersisih",q:"Inovasi yang bertanggung jawab memperhatikan...",options:["Apakah ada kelompok yang tidak bisa mengakses atau memakainya, & mencari cara agar tidak makin tertinggal","Hanya kelompok yang paling menguntungkan bagi pembuatnya karena merekalah yang akan membayar mahal","Tidak peduli siapa yang tertinggal, asalkan sebagian besar orang sudah bisa memakainya dengan baik"],answer:0,explain:"Kalau inovasi hanya menguntungkan yang sudah beruntung, ia bisa memperlebar kesenjangan. Memikirkan akses menjaganya lebih adil.",hint:"Memikirkan yang bisa tertinggal, atau hanya yang menguntungkan?"},
{n:18,type:"mcq",micro:"Inovasi & lingkungan",q:"Aspek lingkungan yang perlu dipikirkan dalam inovasi:",options:["Hanya diperlukan kalau produknya berukuran besar, sedangkan produk kecil tidak berpengaruh pada alam","Bahan yang dipakai, energi yang dibutuhkan, sampah yang dihasilkan, & apa yang terjadi di akhir masa pakainya","Tidak ada yang perlu dipikirkan, sebab lingkungan bukan urusan pembuat melainkan urusan pemerintah"],answer:1,explain:"Setiap benda yang dibuat mengambil sumber daya & meninggalkan jejak. Inovasi yang baik mempertimbangkan seluruh siklusnya.",hint:"Bahan, energi, sampah, akhir pakai, atau bukan urusan pembuat?"},
{n:19,type:"mcq",micro:"Inovasi = memperbaiki, bukan mengganggu tanpa alasan",q:"Sebelum mengganti cara lama dengan cara baru, sebaiknya...",options:["Anggap saja semua cara lama pasti buruk sehingga tidak perlu repot mempelajari kenapa dulu dipakai","Ganti langsung tanpa memahami apa pun supaya inovasinya cepat dipakai dan tidak ada waktu terbuang","Pahami kenapa cara lama ada & apa yang berhasil darinya, agar tidak menghilangkan sesuatu yang penting"],answer:2,explain:"Cara lama sering menyimpan pelajaran. Inovasi yang bijak mempertahankan yang berhasil sambil memperbaiki yang tidak.",hint:"Pahami dulu yang berhasil dari cara lama, atau anggap semua buruk?"},
{n:20,type:"open",micro:"Nilai sebuah inovasi di sekitarmu",q:"Pilih satu hal yang cukup baru dalam hidupmu (aplikasi, kebiasaan sekolah, produk, cara berkomunikasi). Analisis: (a) masalah apa yang ia pecahkan & untuk siapa, (b) apakah masalah itu penting bagi mereka, (c) 2 manfaat nyata & 2 dampak buruk atau biaya (untuk siapa pun, termasuk lingkungan), (d) kesimpulanmu: apakah ini inovasi yang bermanfaat secara keseluruhan, & apa yang akan membuatnya lebih bertanggung jawab.",explain:"Jawaban baik: masalah & pengguna yang jelas, penilaian jujur apakah masalahnya penting, 2 manfaat nyata & 2 dampak buruk/biaya yang benar-benar berbeda (termasuk untuk pihak selain pengguna utama atau lingkungan), & kesimpulan yang menimbang keduanya plus usulan konkret untuk membuatnya lebih bertanggung jawab.",hint:"Untuk (c), pikirkan siapa yang TIDAK memakai inovasi ini, apakah mereka jadi lebih tertinggal?",sample:"Hal: aplikasi pesan cepat yang dipakai kelas untuk koordinasi tugas. (a) Masalah: dulu pengumuman tugas & perubahan jadwal sering tidak sampai ke semua orang, terutama yang absen. Untuk siswa & guru. (b) Penting? Ya, lumayan, karena melewatkan info bisa berarti tugas tidak dikerjakan atau salah bawa buku. (c) Manfaat nyata: (1) informasi sampai cepat ke hampir semua orang, termasuk yang sedang tidak di sekolah; (2) ada catatan tertulis yang bisa dicek ulang, mengurangi salah paham. Dampak buruk/biaya: (1) siswa yang tidak punya HP atau kuota jadi tertinggal & bergantung pada teman, bisa merasa berbeda; (2) grup jadi ramai pesan di luar jam sekolah, mengganggu waktu istirahat & tidur, & kadang muncul obrolan yang menyakiti perasaan. (d) Kesimpulan: secara keseluruhan bermanfaat karena masalah 'info tidak sampai' cukup serius & sekarang jauh berkurang. Yang akan membuatnya lebih bertanggung jawab: menyediakan cara kedua untuk yang tidak punya HP (mis. papan pengumuman kelas yang selalu diperbarui sama isinya), menyepakati aturan grup (jam berapa boleh mengirim, hanya untuk keperluan tugas, tidak untuk menyindir), & guru sesekali mengecek agar tidak ada yang tertinggal atau tersakiti."},
{n:21,type:"classify",micro:"Inovasi bertanggung jawab vs sembrono",q:"Kelompokkan tiap sikap ke 'Inovasi bertanggung jawab' atau 'Inovasi sembrono'.",items:["'Kita cek dulu siapa yang bisa dirugikan sebelum meluncurkan'","'Yang penting cepat rilis, masalah dipikir nanti'","'Kita jujur soal apa yang belum bisa dilakukan alat ini'","'Bilang saja bisa semuanya, biar orang tertarik'"],groups:["Inovasi bertanggung jawab","Inovasi sembrono"],answer:{"Inovasi bertanggung jawab":["'Kita cek dulu siapa yang bisa dirugikan sebelum meluncurkan'","'Kita jujur soal apa yang belum bisa dilakukan alat ini'"],"Inovasi sembrono":["'Yang penting cepat rilis, masalah dipikir nanti'","'Bilang saja bisa semuanya, biar orang tertarik'"]},explain:"Bertanggung jawab: memeriksa dampak, jujur soal batasan. Sembrono: mengabaikan dampak, melebih-lebihkan klaim.",hint:"Memeriksa dampak & jujur, atau abaikan & lebih-lebihkan?"},
{n:22,type:"mcq",micro:"Konsekuensi tak terduga",q:"'Konsekuensi tak terduga' dari inovasi adalah...",options:["Akibat yang tidak direncanakan atau tidak dibayangkan pembuatnya, bisa baik atau buruk","Akibat yang selalu buruk dan merugikan banyak orang setelah sebuah inovasi dipakai secara luas","Akibat yang sudah direncanakan lebih dulu oleh pembuatnya dan ditulis dalam laporan proyeknya"],answer:0,explain:"Contoh buruk: media sosial dirancang menghubungkan orang, ternyata juga menyebarkan hoaks cepat. Memikirkan 'apa lagi yang bisa terjadi' membantu.",hint:"Akibat tak dibayangkan, atau yang direncanakan?"},
{n:23,type:"mcq",micro:"Pemangku kepentingan",q:"'Pemangku kepentingan' (stakeholder) sebuah inovasi adalah...",options:["Hanya pemiliknya","Semua pihak yang terpengaruh atau punya kepentingan atasnya: pengguna, non-pengguna, pembuat, komunitas, lingkungan","Hanya orang yang membayar"],answer:1,explain:"Memetakan pemangku kepentingan memastikan tidak ada kelompok terdampak yang terlupakan saat menilai sebuah inovasi.",hint:"Semua yang terpengaruh, atau hanya yang membayar?"},
{n:24,type:"mcq",micro:"Jangka pendek vs panjang",q:"Sebuah inovasi bisa terlihat bermanfaat dalam jangka pendek tapi merugikan jangka panjang. Contoh cara berpikirnya:",options:["Dampak jangka panjang tidak perlu dipikirkan, sebab yang penting inovasi itu berguna pada saat ini","Kalau sebuah inovasi bermanfaat sekarang, pasti ia akan tetap bermanfaat selamanya bagi semua orang","'Ini menghemat waktu sekarang, tapi apakah membuat keterampilan penting jadi hilang, atau menciptakan ketergantungan?'"],answer:2,explain:"Menimbang dampak sepanjang waktu, bukan hanya saat peluncuran, adalah bagian dari tanggung jawab.",hint:"Timbang jangka panjang juga, atau cukup sekarang?"},
{n:25,type:"mcq",micro:"Menang & kalah",q:"Ketika sebuah inovasi menggantikan cara lama, sering ada pihak yang dirugikan (mis. pekerja yang keahliannya tidak lagi dibutuhkan). Sikap bertanggung jawab:",options:["Akui kerugian itu, & pikirkan cara membantu peralihan (pelatihan ulang, waktu, dukungan), bukan mengabaikannya","Anggap itu sebagai 'harga kemajuan' yang wajar dibayar & bukan urusan pembuat inovasi sama sekali","Sembunyikan fakta bahwa ada pihak yang dirugikan supaya inovasinya tidak ditolak banyak orang"],answer:0,explain:"Kemajuan yang meninggalkan sebagian orang tanpa dukungan bukan kemajuan yang adil. Memikirkan peralihan adalah tanggung jawab bersama.",hint:"Akui & bantu peralihan, atau abaikan sebagai 'harga kemajuan'?"},
{n:26,type:"mcq",micro:"'Bagaimana ini bisa disalahgunakan'",q:"Pertanyaan penting sebelum meluncurkan inovasi:",options:["Tidak perlu memikirkan penyalahgunaan, sebab pengguna pasti memakainya sesuai dengan tujuan pembuat","'Bagaimana ini bisa disalahgunakan untuk merugikan orang, & bagaimana kita mengurangi risiko itu?'","'Bagaimana caranya supaya inovasi ini cepat viral & dibicarakan banyak orang di berbagai media sosial?'"],answer:1,explain:"Alat yang berguna untuk niat baik sering juga bisa dipakai untuk niat buruk. Memikirkannya lebih awal memungkinkan pengaman dirancang.",hint:"Bagaimana bisa disalahgunakan, atau bagaimana jadi viral?"},
{n:27,type:"tf",micro:"Niat baik tidak cukup",q:"Benar atau Salah: Punya niat baik saat membuat sesuatu sudah cukup untuk menjamin inovasi itu tidak merugikan.",answer:false,explain:"Sebaliknya, banyak inovasi dengan niat baik menimbulkan kerugian karena dampaknya tidak dipikirkan. Niat baik perlu ditemani pemeriksaan dampak yang serius.",hint:"Niat baik cukup, atau perlu ditemani pemeriksaan dampak?"},
{n:28,type:"tf",micro:"Inovasi & tanggung jawab pembuat",q:"Benar atau Salah: Pembuat sebuah inovasi hanya bertanggung jawab atas niat baiknya, bukan atas dampak yang sebenarnya bisa mereka perkirakan.",answer:false,explain:"Sebaliknya, 'aku kan cuma bikin, bukan salahku dipakai begitu' tidak sepenuhnya lepas tanggung jawab bila dampaknya bisa diperkirakan & dikurangi lewat desain.",hint:"Bertanggung jawab atas desain & dampak yang bisa diperkirakan, atau hanya atas niat?"},
{n:29,type:"mcq",micro:"Data & privasi",q:"Inovasi yang mengumpulkan data orang bertanggung jawab bila...",options:["Mengumpulkan data sebanyak mungkin untuk berjaga-jaga kalau suatu saat nanti ternyata diperlukan","Menyembunyikan fakta bahwa data dikumpulkan supaya pengguna tidak merasa curiga & tetap mau memakainya","Hanya mengumpulkan yang benar-benar perlu, menjelaskan untuk apa, menjaganya aman, & memberi orang kendali atasnya"],answer:2,explain:"Data adalah milik orang. Mengumpulkan seperlunya, transparan, & memberi kendali adalah dasar inovasi yang menghormati privasi.",hint:"Seperlunya & transparan, atau sebanyak mungkin & disembunyikan?"},
{n:30,type:"order",micro:"Analisis dampak sederhana",q:"Urutkan langkah menganalisis dampak sebuah inovasi.",items:["Daftar semua pemangku kepentingan (yang terpengaruh)","Untuk tiap pihak, tulis dampak positif & negatif yang mungkin, jangka pendek & panjang","Tandai dampak negatif yang serius atau mengenai pihak yang rentan","Ubah desain untuk mengurangi dampak itu, atau putuskan apakah manfaatnya sepadan"],answer:[0,1,2,3],explain:"Daftar pihak → dampak dua arah & dua waktu → tandai yang serius → perbaiki atau timbang. Analisis mengarah pada tindakan, bukan hanya daftar.",hint:"Menandai dampak serius sebelum atau sesudah mendaftar semua dampak?"},
{n:31,type:"mcq",micro:"Rentan lebih diperhatikan",q:"Kenapa dampak pada kelompok rentan (anak kecil, lansia, orang miskin, penyandang disabilitas) perlu perhatian lebih?",options:["Mereka sering punya lebih sedikit pilihan & kekuatan untuk melindungi diri dari dampak buruk","Mereka tidak penting karena jumlahnya sedikit sehingga dampak pada mereka bisa diabaikan saja","Mereka selalu otomatis diuntungkan oleh setiap inovasi sehingga tidak perlu dikhawatirkan sama sekali"],answer:0,explain:"Inovasi yang bertanggung jawab memberi bobot lebih pada dampak terhadap mereka yang paling sulit menghindari kerugian.",hint:"Lebih sedikit pilihan melindungi diri, atau tidak penting?"},
{n:32,type:"tf",micro:"Manfaat bagi mayoritas & kerugian minoritas",q:"Benar atau Salah: Kalau sebuah inovasi menguntungkan mayoritas, tidak perlu lagi memeriksa apakah ada minoritas yang dirugikan berat.",answer:false,explain:"Sebaliknya, 'baik untuk kebanyakan orang' tidak otomatis membenarkan kerugian besar pada sebagian. Keduanya perlu ditimbang, & peringanan diupayakan.",hint:"Tetap periksa kerugian minoritas, atau cukup untung mayoritas?"},
{n:33,type:"mcq",micro:"Klaim yang bisa dibuktikan",q:"Saat inovasi mengklaim manfaat (mis. 'menghemat 50% waktu'), tanggung jawabnya:",options:["Klaim tidak perlu bukti, sebab pembuat inovasi pasti lebih tahu manfaat dari karyanya sendiri","Klaim itu bisa ditunjukkan dengan bukti nyata, bukan angka yang dikarang agar menarik","Angka apa pun boleh dipakai selama terdengar meyakinkan dan membuat orang tertarik pada inovasinya"],answer:1,explain:"Klaim tanpa bukti menyesatkan pengguna dalam mengambil keputusan. Kejujuran klaim adalah bagian dari inovasi yang bertanggung jawab.",hint:"Didukung bukti, atau angka yang dikarang?"},
{n:34,type:"mcq",micro:"Keberlanjutan inovasi",q:"Inovasi yang bertanggung jawab juga memikirkan...",options:["Hanya momen peluncuran saja yang penting, sebab setelah itu inovasinya bukan tanggung jawab pembuat lagi","Bagaimana caranya cepat menggantinya dengan versi baru begitu pengguna mulai merasa bosan padanya","Apakah ia bisa dirawat & bertahan setelah antusiasme awal, tanpa membebani orang atau sumber daya secara tidak wajar"],answer:2,explain:"Solusi yang bagus tapi tidak bisa dirawat akan mati & meninggalkan pengguna yang sudah bergantung padanya. Keberlanjutan adalah tanggung jawab.",hint:"Bisa dirawat & bertahan, atau hanya momen peluncuran?"},
{n:35,type:"mcq",micro:"Inovasi & kejujuran tentang ketidakpastian",q:"Kalau dampak jangka panjang sebuah inovasi belum jelas, sikap bertanggung jawab:",options:["Akui ketidakpastian itu, mulai dari skala kecil, pantau dampaknya, & siap menyesuaikan","Klaim saja bahwa inovasi itu aman sepenuhnya walau belum ada dasar untuk menyatakan hal tersebut","Berhenti berinovasi sama sekali karena tidak ada satu pun dampak jangka panjang yang bisa dipastikan"],answer:0,explain:"Ketidakpastian bukan alasan berhenti maupun alasan sembrono. Ia alasan untuk berhati-hati: kecil dulu, pantau, sesuaikan.",hint:"Akui, mulai kecil, pantau, atau klaim aman / berhenti total?"},
{n:36,type:"mcq",micro:"Melibatkan yang terdampak",q:"Cara mengurangi risiko inovasi merugikan orang secara tak sengaja:",options:["Baru tanyakan pendapat mereka sesudah semuanya selesai dibuat dan siap diluncurkan, supaya mereka hanya perlu menyetujuinya","Libatkan wakil dari kelompok yang akan terdampak dalam merancang & menilai, mereka melihat risiko yang tidak terlihat pembuat","Rancang sendiri saja berdasarkan bayangan tim tentang mereka, karena kita sudah cukup memahami apa yang mereka rasakan"],answer:1,explain:"Orang yang akan hidup dengan dampak sebuah inovasi sering paling awal melihat masalahnya. Suara mereka dalam proses adalah pengaman.",hint:"Libatkan mereka dalam merancang, atau rancang sendiri?"},
{n:37,type:"tf",micro:"Berhenti juga pilihan",q:"Benar atau Salah: Memutuskan untuk tidak melanjutkan sebuah inovasi karena risikonya terlalu besar selalu berarti kita gagal & kurang berani.",answer:false,explain:"Sebaliknya, tidak setiap ide yang bisa dibuat sebaiknya dibuat. Menahan diri saat risikonya melebihi manfaat & tidak bisa dikurangi adalah keputusan yang sah & kadang paling bertanggung jawab.",hint:"Berhenti bisa jadi keputusan tepat, atau harus selalu lanjut?"},
{n:38,type:"mcq",micro:"Inovasi & ketergantungan",q:"Inovasi yang membuat pengguna sangat bergantung (mis. tidak bisa lagi melakukan hal dasar tanpanya) perlu dipikirkan karena...",options:["Ketergantungan pengguna selalu baik untuk bisnis sehingga tidak perlu dipikirkan sisi buruknya","Tidak ada yang perlu dipikirkan, sebab pengguna yang bergantung berarti inovasinya sudah sangat berhasil","Kalau layanan berhenti atau alat rusak, pengguna bisa sangat kesulitan; & keterampilan penting bisa hilang"],answer:2,explain:"Inovasi yang bertanggung jawab berusaha memberdayakan, bukan menjebak. Idealnya pengguna tetap punya pilihan & keterampilan cadangan.",hint:"Kesulitan besar bila berhenti & keterampilan hilang, atau tidak perlu dipikirkan?"},
{n:39,type:"mcq",micro:"Inovasi meniru vs mencuri",q:"Membangun di atas ide orang lain jadi bertanggung jawab bila...",options:["Kita menambahkan nilai nyata, mengakui sumbernya, & menghormati hak yang dilindungi (paten, hak cipta)","Kita menyalin persis ide itu lalu mengklaimnya sebagai milik sendiri supaya orang mengira kita pencipta","Kita menyembunyikan dari mana idenya berasal supaya tidak ada yang bisa menuntut hak atas ide tersebut"],answer:0,explain:"Hampir semua inovasi membangun di atas karya sebelumnya. Yang membedakan: menambah nilai, jujur soal sumber, & menghormati hak.",hint:"Menambah nilai & mengakui sumber, atau menyalin & mengklaim?"},
{n:40,type:"open",micro:"Analisis dampak sebuah inovasi",q:"Bayangkan sekolahmu akan memasang 'sistem pengenalan wajah' untuk absensi otomatis di gerbang. Buat analisis dampak: (a) daftar minimal 4 pemangku kepentingan, (b) untuk masing-masing, dampak positif & negatif yang mungkin, (c) 1 kemungkinan penyalahgunaan & cara menguranginya, (d) 1 kelompok yang mungkin tersisih/dirugikan, (e) kesimpulanmu: layak dilanjutkan seperti apa, dengan syarat apa, atau tidak.",explain:"Jawaban baik: minimal 4 pemangku kepentingan dengan dampak dua arah yang masuk akal (termasuk pihak yang kepentingannya bisa mendorong ke arah kurang baik), satu skenario penyalahgunaan yang nyata dengan cara mengurangi yang konkret, identifikasi kelompok yang bisa dirugikan oleh kesalahan sistem atau ketiadaan pilihan, & kesimpulan yang berani mengambil posisi (termasuk 'tidak' atau 'hanya dengan syarat ketat') berdasar analisisnya, bukan sekadar 'ada plus minus'.",hint:"Untuk kesimpulan, ingat: kalau ada cara jauh lebih ringan menyelesaikan masalah yang sama, inovasi yang lebih berisiko sering tidak sepadan.",sample:"(a) Pemangku kepentingan: siswa, guru & staf, wali murid, pihak sekolah/administrasi, & penyedia teknologi. (b) Dampak: Siswa, positif, tidak perlu antre tanda tangan, tercatat otomatis; negatif, wajahnya dipindai & disimpan setiap hari, merasa diawasi, & bisa salah kenali (terutama kalau berganti penampilan atau memakai masker). Guru/staf, positif, hemat waktu rekap; negatif, harus menangani kegagalan sistem & keluhan, & juga ikut dipindai. Wali murid, positif, info kehadiran cepat & akurat; negatif, khawatir soal keamanan data anak & siapa yang bisa mengaksesnya. Sekolah, positif, data rapi, mengurangi titip-absen; negatif, biaya alat & perawatan, tanggung jawab hukum kalau data bocor. Penyedia teknologi, positif, mendapat kontrak & data; negatif (bagi pihak lain), kepentingannya bisa mendorong pengumpulan data lebih banyak dari yang perlu. (c) Kemungkinan penyalahgunaan: data wajah & jejak kehadiran dipakai untuk melacak pergerakan siswa di luar tujuan absensi, atau dijual/dibagikan. Cara mengurangi: aturan tertulis yang mengikat, data hanya untuk absensi, disimpan terbatas waktu lalu dihapus, tidak boleh dibagikan ke pihak ketiga, & ada yang mengawasi kepatuhannya. (d) Kelompok yang bisa dirugikan/tersisih: siswa yang datanya sering gagal dikenali (kondisi kulit, disabilitas wajah, sering berganti tampilan) bisa berulang kali dianggap tidak hadir & harus membuktikan diri, itu memalukan & melelahkan. Juga siswa/keluarga yang keberatan secara prinsip soal pemindaian wajah tapi tidak punya kekuatan menolak. (e) Kesimpulan: menurutku sebaiknya TIDAK memakai pengenalan wajah untuk masalah ini, risikonya (privasi, data anak, potensi penyalahgunaan, kesalahan yang merugikan sebagian siswa) besar & sulit dikurangi, sementara masalah 'absensi lambat' bisa diselesaikan dengan cara yang jauh lebih ringan, misalnya kartu tap atau QR dengan jalur manual, tanpa menyimpan data biometrik. Kalau tetap dilanjutkan, syarat minimalnya: ada pilihan tidak ikut yang setara & tidak memalukan, data biometrik tidak disimpan (hanya dicocokkan lalu dihapus), aturan tertulis yang diawasi, & persetujuan wali murid yang benar-benar bebas."},
{n:41,type:"mcq",micro:"Uji 'sisi gelap'",q:"'Uji sisi gelap' sebuah inovasi berarti sengaja bertanya...",options:["Tidak ada yang perlu ditanyakan, sebab bertanya tentang niat buruk itu terlalu pesimis dan berlebihan","'Kalau orang dengan niat buruk memakai ini, apa yang bisa mereka lakukan? Bagaimana kita menyulitkannya?'","'Bagaimana caranya membuat inovasi ini terlihat sempurna tanpa celah sedikit pun di depan semua orang?'"],answer:1,explain:"Membayangkan penyalahgunaan lebih awal memungkinkan pengaman dirancang masuk, bukan ditambal setelah terjadi kerugian.",hint:"Bayangkan niat buruk & rancang pengaman, atau anggap terlalu pesimis?"},
{n:42,type:"mcq",micro:"Prinsip 'tidak merugikan dulu'",q:"Prinsip 'setidaknya, jangan merugikan' dalam inovasi berarti...",options:["Jangan pernah membuat apa pun yang mengandung risiko sekecil apa pun, karena risiko selalu berbahaya","Manfaat besar selalu lebih penting daripada kerugian apa pun, sehingga kerugian boleh diabaikan saja","Sebelum mengejar manfaat besar, pastikan dulu inovasi ini tidak menimbulkan kerugian serius yang bisa dihindari"],answer:2,explain:"Ini ambang minimum: boleh belum sempurna, tapi jangan sampai menyakiti orang dengan cara yang sebenarnya bisa dicegah.",hint:"Cegah kerugian serius yang bisa dihindari dulu, atau kejar manfaat apa pun risikonya?"},
{n:43,type:"mcq",micro:"Mulai kecil, pantau",q:"Untuk inovasi yang dampaknya belum jelas, cara meluncurkan yang bertanggung jawab:",options:["Uji di kelompok kecil dulu, pantau dampak baik & buruk, sesuaikan sebelum memperluas","Luncurkan langsung ke semua orang sekaligus supaya dampaknya terasa maksimal & cepat dikenal banyak pihak","Sembunyikan dulu sampai yakin sempurna, lalu luncurkan besar-besaran dengan satu acara peluncuran megah"],answer:0,explain:"Skala kecil membuat kerugian tak terduga tetap kecil & bisa diperbaiki. Ini seperti prototipe, tapi untuk dampak sosialnya.",hint:"Kecil dulu & pantau, atau semua sekaligus?"},
{n:44,type:"mcq",micro:"Transparansi",q:"Transparan tentang sebuah inovasi berarti...",options:["Memakai istilah-istilah rumit & teknis yang panjang agar terlihat sangat pintar dan membuat pengguna langsung percaya padanya","Menjelaskan cara kerjanya, data yang dipakai, batasannya, & siapa yang bertanggung jawab, dengan bahasa yang bisa dipahami pengguna","Merahasiakan cara kerjanya dari semua orang agar tidak ditiru oleh pihak lain, dan hanya menyebut hasil akhirnya saja kepada pengguna"],answer:1,explain:"Pengguna berhak tahu apa yang mereka pakai & percayai. Transparansi memungkinkan mereka membuat pilihan sadar.",hint:"Jelas & bisa dipahami, atau dirahasiakan / dibuat rumit?"},
{n:45,type:"tf",micro:"Memberi pilihan",q:"Benar atau Salah: Inovasi yang bertanggung jawab, bila memungkinkan, memberi orang pilihan untuk tidak memakainya tanpa dirugikan secara tidak adil.",answer:true,explain:"Memaksa semua orang memakai sesuatu, terutama yang menyangkut data atau tubuh mereka, menghilangkan hak memilih. Menyediakan alternatif yang setara menghormati itu.",hint:"Beri pilihan tidak ikut yang setara, atau paksa semua?"},
{n:46,type:"mcq",micro:"Menimbang trade-off secara terbuka",q:"Kalau sebuah inovasi punya manfaat besar tapi juga satu kerugian yang tidak bisa dihilangkan sepenuhnya, sikap yang jujur:",options:["Sembunyikan kerugian itu dari pihak yang terdampak supaya mereka tidak menolak inovasi yang bermanfaat","Batalkan seluruh inovasi itu karena inovasi yang tidak bisa sempurna lebih baik tidak pernah dibuat","Nyatakan trade-off itu secara terbuka ke pihak yang terdampak & upayakan mengurangi kerugiannya, bukan menyembunyikannya"],answer:2,explain:"Keputusan yang jujur mengakui: 'ini yang kami dapat, ini yang kami korbankan, ini yang kami lakukan untuk pihak yang menanggungnya'.",hint:"Nyatakan terbuka & kurangi, atau sembunyikan / batalkan?"},
{n:47,type:"mcq",micro:"Inklusi dalam desain",q:"Merancang inovasi yang inklusif berarti...",options:["Memastikan sebanyak mungkin orang bisa mengaksesnya & memakainya, termasuk yang berkebutuhan khusus, sejak awal","Merancang hanya untuk 'pengguna rata-rata' saja & mengabaikan mereka yang kebutuhannya berbeda dari kebanyakan","Membuat versi terpisah yang lebih sederhana dan lebih buruk untuk kelompok tertentu, ditambahkan nanti"],answer:0,explain:"Desain inklusif sering menghasilkan solusi yang lebih baik untuk semua orang, bukan hanya kelompok yang tadinya terlupakan.",hint:"Bisa diakses banyak orang sejak awal, atau untuk 'rata-rata' saja?"},
{n:48,type:"mcq",micro:"Mengukur dampak nyata",q:"Setelah inovasi berjalan, cara bertanggung jawab menilainya:",options:["Anggap saja inovasinya berhasil karena idenya bagus sejak awal, sudah dipikirkan matang oleh tim, dan disetujui oleh semua anggota","Kumpulkan bukti nyata: apakah masalah yang dituju benar-benar berkurang? adakah masalah baru yang muncul? siapa yang terbantu & siapa yang tidak?","Cukup lihat apakah banyak orang yang memakainya, sebab jumlah pengguna yang besar pasti tanda bahwa inovasinya benar-benar bermanfaat"],answer:1,explain:"Popularitas bukan bukti manfaat. Menilai dampak sebenarnya (masalah berkurang? masalah baru?) menjaga inovasi tetap jujur pada tujuannya.",hint:"Bukti dampak nyata, atau cukup jumlah pemakai?"},
{n:49,type:"mcq",micro:"Menanggapi dampak buruk yang muncul",q:"Setelah diluncurkan, ternyata inovasimu menimbulkan masalah yang tidak terduga. Sikap bertanggung jawab:",options:["Sembunyikan masalah itu sampai ada pihak yang protes keras, supaya reputasi inovasimu tetap terjaga","Salahkan para pengguna karena 'memakainya dengan cara yang salah' padahal rancanganmu yang membingungkan","Akui secepatnya, hentikan atau batasi bila perlu, perbaiki, & beri tahu yang terdampak"],answer:2,explain:"Bagaimana kita menanggapi dampak buruk yang muncul adalah ujian tanggung jawab yang sesungguhnya, bukan hanya niat di awal.",hint:"Akui & perbaiki cepat, atau sembunyikan / salahkan pengguna?"},
{n:50,type:"order",micro:"Merancang pengaman ke dalam inovasi",q:"Urutkan langkah membangun pengaman ke dalam sebuah inovasi.",items:["Bayangkan cara-cara inovasi ini bisa disalahgunakan atau merugikan tanpa sengaja","Urutkan risiko dari yang paling serius/mungkin","Untuk risiko teratas, rancang batasan, peringatan, atau fitur yang menyulitkan penyalahgunaan","Uji apakah pengaman itu bekerja tanpa membuat inovasi tak berguna bagi pemakai yang baik"],answer:[0,1,2,3],explain:"Bayangkan penyalahgunaan → urutkan risiko → rancang pengaman untuk yang teratas → uji keseimbangannya. Pengaman dirancang masuk, bukan ditempel belakangan.",hint:"Merancang pengaman sebelum atau sesudah mengurutkan risiko?"},
{n:51,type:"mcq",micro:"Inovasi & komunitas lokal",q:"Saat membawa inovasi ke komunitas tertentu, yang bertanggung jawab:",options:["Memahami kebutuhan, nilai, & keterbatasan komunitas itu, & menyesuaikan, bukan memaksakan solusi 'satu ukuran untuk semua'","Terapkan persis seperti yang dilakukan di tempat lain karena cara itu sudah terbukti berhasil di sana","Anggap komunitas itu yang harus menyesuaikan diri dengan inovasinya, bukan inovasi yang menyesuaikan diri"],answer:0,explain:"Solusi yang berhasil di satu konteks bisa gagal atau merugikan di konteks lain. Menyesuaikan dengan hormat adalah bagian dari tanggung jawab.",hint:"Sesuaikan dengan komunitas, atau paksakan 'satu ukuran'?"},
{n:52,type:"tf",micro:"Kejujuran klaim melindungi kepercayaan",q:"Benar atau Salah: Melebih-lebihkan manfaat inovasi mungkin menarik perhatian dalam jangka pendek, tapi merusak kepercayaan begitu pengguna kecewa.",answer:true,explain:"Kepercayaan sulit dibangun & mudah rusak. Klaim jujur yang mungkin kurang mengesankan lebih kuat dalam jangka panjang.",hint:"Melebih-lebihkan merusak kepercayaan, atau tidak berpengaruh?"},
{n:53,type:"mcq",micro:"Inovasi & pekerjaan",q:"Kalau inovasimu bisa menghilangkan pekerjaan orang, cara bertanggung jawab memikirkannya:",options:["Rahasiakan kemungkinan itu dari semua orang supaya inovasimu tidak ditolak sebelum sempat dicoba","Pertimbangkan apakah inovasi bisa membantu pekerja bekerja lebih baik (bukan menggantikan), atau bagaimana peralihan bisa didukung","Anggap saja hal itu bukan urusanmu, karena tugas pembuat inovasi hanyalah membuat dan bukan memikirkan akibatnya"],answer:1,explain:"Dampak pada mata pencaharian orang adalah dampak serius. Memikirkan 'memberdayakan bukan menggantikan' atau 'mendukung peralihan' adalah bagian dari tanggung jawab.",hint:"Pertimbangkan memberdayakan / mendukung peralihan, atau abaikan?"},
{n:54,type:"mcq",micro:"Menguji dengan kelompok beragam",q:"Menguji inovasi hanya dengan orang yang mirip pembuatnya berisiko...",options:["Tidak berisiko sama sekali, sebab orang yang mirip pembuatnya sudah cukup mewakili semua pengguna lainnya","Membuat hasil uji menjadi lebih akurat karena semua penguji punya kebiasaan dan kebutuhan yang sama","Melewatkan masalah yang dialami kelompok lain, yang baru muncul setelah dipakai luas"],answer:2,explain:"Kelompok penguji yang seragam punya titik buta bersama. Keragaman penguji menemukan masalah lebih awal & lebih lengkap.",hint:"Melewatkan masalah kelompok lain, atau lebih akurat?"},
{n:55,type:"mcq",micro:"Dokumentasi keputusan",q:"Mencatat 'kenapa kami memutuskan begini' (termasuk risiko yang dipertimbangkan) berguna karena...",options:["Bila dampak buruk muncul, kita bisa menelusuri & memperbaiki; & orang berikutnya belajar dari pertimbangan kita","Membuat pekerjaan terlihat lebih banyak","Tidak berguna"],answer:0,explain:"Jejak keputusan membuat inovasi bisa dipertanggungjawabkan & diperbaiki, & menjadi pelajaran untuk yang datang kemudian.",hint:"Bisa ditelusuri & jadi pelajaran, atau sekadar terlihat banyak?"},
{n:56,type:"tf",micro:"Bertanggung jawab bukan berarti tidak berani",q:"Benar atau Salah: Inovasi yang bertanggung jawab berarti hanya boleh membuat hal-hal kecil & aman, tidak boleh berani atau ambisius.",answer:false,explain:"Sebaliknya, tanggung jawab & keberanian berjalan bersama: berani mencoba hal yang berarti, sambil serius memikirkan & mengelola dampaknya.",hint:"Tetap bisa berani, atau harus selalu kecil & aman?"},
{n:57,type:"mcq",micro:"Menyeimbangkan kecepatan & kehati-hatian",q:"Ketika ada tekanan untuk 'cepat rilis', pertanyaan yang menjaga tanggung jawab:",options:["'Kecepatan peluncuran selalu lebih penting daripada hal lain, jadi pemeriksaan boleh dikorbankan kapan saja.'","'Risiko mana yang tidak boleh kita lewati pemeriksaannya, meski itu berarti sedikit lebih lambat?'","'Bagaimana caranya melewati semua pemeriksaan yang ada supaya inovasinya bisa dirilis secepat mungkin?'"],answer:1,explain:"Beberapa pemeriksaan (keselamatan, dampak pada yang rentan, privasi) tidak boleh dikorbankan demi kecepatan. Yang lain bisa menyusul.",hint:"Jaga pemeriksaan yang tidak boleh dilewati, atau kecepatan di atas segalanya?"},
{n:58,type:"mcq",micro:"Umpan balik berkelanjutan",q:"Setelah inovasi berjalan, cara menjaganya tetap bertanggung jawab:",options:["Anggap tugasnya sudah selesai begitu inovasi diluncurkan sebab pembuat tidak perlu mengurusnya lagi","Tutup semua saluran keluhan supaya pengguna tidak mengganggu dengan laporan yang bisa membuat kita ragu","Sediakan saluran bagi pengguna & pihak terdampak untuk melaporkan masalah, & tanggapi laporan itu sungguh-sungguh"],answer:2,explain:"Dampak berkembang seiring pemakaian. Mendengarkan terus & menanggapi adalah bagian dari tanggung jawab yang tidak berhenti di peluncuran.",hint:"Sediakan & tanggapi saluran laporan, atau anggap selesai?"},
{n:59,type:"mcq",micro:"Inovasi & kejujuran pada diri sendiri",q:"Godaan yang perlu diwaspadai saat menilai dampak inovasi sendiri:",options:["Cenderung meremehkan risiko & membesarkan manfaat karena kita ingin idenya berhasil","Cenderung terlalu keras menilai ide sendiri sehingga manfaat yang sebenarnya justru selalu diremehkan","Selalu menilai dengan sangat adil dan tepat karena kita adalah orang yang paling mengenal inovasinya"],answer:0,explain:"Menyadari bias ini penting: sengaja mencari pihak yang tidak bersemangat & minta mereka menunjukkan kelemahan yang kita lewatkan.",hint:"Meremehkan risiko sendiri, atau selalu adil?"},
{n:60,type:"open",micro:"Rancang inovasi dengan pengaman",q:"Pilih satu ide inovasi (milikmu atau contoh). Tulis: (a) masalah & pengguna yang dituju, (b) daftar 4 pemangku kepentingan, (c) 3 kemungkinan dampak buruk atau penyalahgunaan, (d) untuk masing-masing, satu pengaman atau perubahan desain untuk menguranginya, (e) satu hal yang tidak bisa kamu hilangkan sepenuhnya & bagaimana kamu akan jujur tentangnya, (f) rencana meluncurkan secara bertahap & memantau dampak.",explain:"Jawaban baik: masalah & pengguna jelas, 4 pemangku kepentingan termasuk yang rentan (pemalu, berkebutuhan khusus), 3 dampak buruk yang nyata & berbeda, pengaman konkret untuk masing-masing (bukan sekadar 'akan hati-hati'), pengakuan jujur atas risiko yang tersisa dengan cara mengomunikasikannya, & rencana peluncuran kecil-dulu dengan pemantauan yang benar-benar menanyakan kelompok rentan & siap menghentikan bila merugikan.",hint:"Bagian (e) penting, hampir semua inovasi punya risiko yang tak bisa dihapus total; tanggung jawab berarti mengakuinya, bukan berpura-pura tidak ada.",sample:"Ide: 'papan peringkat kelas' digital yang menampilkan poin kebaikan (membantu teman, piket, dll) yang dikumpulkan siswa, untuk mendorong perilaku baik. (a) Masalah: perilaku saling membantu jarang diperhatikan & dihargai; pengguna, siswa & wali kelas. (b) Pemangku kepentingan: siswa yang aktif membantu, siswa yang pemalu/introvert, wali kelas, & wali murid. (c) Dampak buruk/penyalahgunaan: (1) berubah jadi kompetisi yang membuat siswa membantu hanya demi poin, bukan tulus, & memandang rendah yang poinnya sedikit; (2) siswa yang pemalu atau punya keterbatasan (mis. tidak bisa ikut piket berat) selalu di bawah & merasa buruk; (3) poin bisa 'dikarang' atau diberikan pilih kasih oleh yang mencatat. (d) Pengaman: (1) tidak menampilkan peringkat individual berurutan, cukup total kelas & 'sorotan minggu ini' yang bergilir & menyebut perbuatan spesifik, bukan siapa paling banyak; (2) definisi 'kebaikan' dibuat luas & mencakup hal kecil yang bisa dilakukan semua orang (menyapa, meminjamkan alat, menghibur teman), & poin tidak pernah negatif; (3) pencatatan dilakukan berpasangan/bergilir dengan aturan jelas, & wali kelas meninjau berkala. (e) Yang tidak bisa dihilangkan sepenuhnya: selalu ada risiko sebagian siswa tetap termotivasi oleh 'hadiah', bukan ketulusan. Aku akan jujur soal ini ke kelas & wali kelas: 'Papan ini alat untuk membuat kita lebih sadar & menghargai kebaikan, bukan lomba. Kalau terasa jadi lomba, kita ubah atau hentikan.' (f) Peluncuran bertahap: coba di satu kelas selama sebulan tanpa hadiah apa pun, hanya sorotan bergilir; setelah dua minggu, tanya siswa (termasuk yang pemalu) bagaimana perasaan mereka & apakah terasa seperti lomba; kalau menimbulkan perbandingan yang menyakiti, ubah bentuknya atau hentikan; kalau membantu, baru pertimbangkan memperluas ke kelas lain dengan pelajaran yang didapat."},
{n:61,type:"mcq",micro:"Dilema kemajuan vs risiko",q:"Sebuah inovasi bisa sangat membantu banyak orang tapi juga membawa risiko baru yang serius. Cara berpikir yang matang:",options:["Selalu tolak apa pun yang mengandung risiko, sebab keselamatan harus lebih utama daripada manfaat apa pun yang dijanjikan inovasi itu","Timbang besarnya manfaat vs besarnya & kemungkinan risiko, cari cara mengurangi risiko, & putuskan dengan sadar akan yang dipertaruhkan","Selalu pilih kemajuan apa pun risikonya, sebab inovasi yang berhenti hanya karena rasa takut tidak akan pernah membawa kebaikan bagi dunia"],answer:1,explain:"Bukan 'maju terus' atau 'jangan berubah', melainkan penilaian yang jujur & keputusan sadar dengan pengurangan risiko semaksimal mungkin.",hint:"Timbang & kurangi risiko lalu putuskan sadar, atau selalu satu ekstrem?"},
{n:62,type:"mcq",micro:"'Kalau bukan kita, orang lain juga akan buat'",q:"Argumen 'kalau kita tidak membuatnya, orang lain akan membuatnya juga' sebagai alasan mengabaikan dampak...",options:["Sepenuhnya membenarkan kita untuk mengabaikan dampak, sebab kalau bukan kita yang membuatnya, orang lain pasti melakukannya dengan cara yang sama","Berarti dampak tidak perlu dipikirkan sama sekali, karena hasil akhirnya akan sama saja siapa pun pembuatnya dan bagaimana pun rancangannya","Tidak menghapus tanggung jawab kita atas pilihan & rancangan kita sendiri; kita masih bisa memilih membuatnya lebih aman atau tidak membuatnya"],answer:2,explain:"Bahwa orang lain mungkin bertindak buruk bukan alasan kita ikut. Kita bertanggung jawab atas keputusan kita, & bisa menjadi contoh yang lebih baik.",hint:"Tanggung jawab kita tetap ada, atau hilang karena orang lain juga akan buat?"},
{n:63,type:"mcq",micro:"Siapa yang menanggung risiko vs siapa yang untung",q:"Ketidakadilan dalam sebuah inovasi sering terlihat ketika...",options:["Pihak yang menikmati keuntungan berbeda dari pihak yang menanggung risiko atau kerugiannya","Semua orang mendapat untung yang sama besar sehingga tidak ada yang merasa dirugikan oleh inovasinya","Pembuatnya juga ikut memakai inovasi itu sehingga ia mengerti betul apa yang dirasakan oleh pengguna lain"],answer:0,explain:"Mis. pabrik untung, warga sekitar menanggung polusi. Memeriksa 'siapa untung, siapa menanggung' mengungkap ketidakadilan yang perlu diperbaiki.",hint:"Yang untung beda dari yang menanggung risiko, atau semua sama?"},
{n:64,type:"tf",micro:"Tanggung jawab tidak berakhir di peluncuran",q:"Benar atau Salah: Tanggung jawab pembuat inovasi berlanjut setelah peluncuran, memantau dampak, menanggapi masalah, & memperbaiki bila perlu.",answer:true,explain:"Dampak sebuah inovasi terus berkembang seiring pemakaian. 'Sudah kuluncurkan, selesai' bukan sikap yang bertanggung jawab.",hint:"Berlanjut setelah peluncuran, atau selesai saat rilis?"},
{n:65,type:"mcq",micro:"Menolak tekanan yang tidak etis",q:"Kamu diminta membuat fitur yang kamu yakini akan merugikan pengguna (mis. membuat sulit berhenti berlangganan). Sikap:",options:["Diam saja & berharap tidak ada yang menyadari bahwa fitur itu sebenarnya dibuat untuk merugikan pengguna, supaya tidak terjadi perselisihan di dalam tim","Sampaikan keberatan dengan alasan jelas, usulkan alternatif yang jujur, & bila tetap diminta, pertimbangkan batas yang tidak akan kamu langgar","Kerjakan saja sesuai perintah karena itu tugasmu, dan semua tanggung jawab atas akibat buruknya sepenuhnya ada pada orang yang menyuruhmu"],answer:1,explain:"Menjadi bagian dari inovasi yang bertanggung jawab kadang berarti berani menyuarakan keberatan & menolak melanggar prinsip.",hint:"Suarakan keberatan & usulkan alternatif, atau kerjakan saja / diam?"},
{n:66,type:"mcq",micro:"Inovasi & keadilan antargenerasi",q:"'Keadilan antargenerasi' dalam inovasi berarti mempertimbangkan...",options:["Hanya kebutuhan generasi yang hidup sekarang, sebab generasi mendatang bisa mengurus dirinya sendiri nanti","Hanya generasi mendatang saja, sedangkan kebutuhan generasi yang sekarang boleh dikorbankan untuk masa depan","Apakah manfaat sekarang dibayar dengan kerugian bagi orang di masa depan (mis. sumber daya habis, lingkungan rusak)"],answer:2,explain:"Inovasi yang bertanggung jawab tidak 'meminjam' dari masa depan tanpa memikirkan siapa yang akan membayarnya.",hint:"Timbang dampak pada masa depan, atau hanya sekarang?"},
{n:67,type:"mcq",micro:"Membedakan kritik sehat dari penghambat",q:"Ketika seseorang menunjukkan risiko dari inovasimu, respons yang matang:",options:["Dengarkan sungguh-sungguh & periksa apakah risikonya nyata, meski itu tidak nyaman & memperlambat","Anggap mereka 'anti-kemajuan' & abaikan saja peringatannya supaya proyek tetap berjalan sesuai jadwal","Serang balik pribadinya dengan menyebut bahwa ia tidak mengerti teknologi supaya orang lain tidak percaya"],answer:0,explain:"Orang yang menunjukkan risiko sering membantu, bukan menghambat. Memeriksa kritik dengan jujur membuat inovasi lebih kuat.",hint:"Periksa risikonya dengan jujur, atau labeli 'anti-kemajuan'?"},
{n:68,type:"tf",micro:"Sebagian ide sebaiknya tidak dibuat",q:"Benar atau Salah: Ada ide yang secara teknis bisa dibuat tetapi sebaiknya tidak dibuat karena kerugian atau bahayanya jauh melebihi manfaatnya & tidak bisa dikurangi.",answer:true,explain:"Kemampuan membuat sesuatu tidak otomatis berarti kita harus membuatnya. Menahan diri adalah pilihan yang sah & kadang paling bertanggung jawab.",hint:"Sebagian sebaiknya tidak dibuat, atau semua yang bisa dibuat harus dibuat?"},
{n:69,type:"mcq",micro:"Inovasi & konsentrasi kekuatan",q:"Inovasi yang memberi kekuatan besar (informasi, kendali, pengaruh) pada sedikit pihak perlu dipikirkan karena...",options:["Itu bukan urusan pembuat inovasi, karena pengawasan hanya menjadi tugas pemerintah dan para penegak hukum","Kekuatan yang terpusat bisa disalahgunakan & sulit diimbangi; perlu ada pengawasan, batas, atau pembagian","Pemusatan kekuatan selalu efisien & baik bagi semua orang sehingga tidak perlu dibatasi atau diawasi"],answer:1,explain:"Inovasi yang bertanggung jawab memikirkan bukan hanya 'apakah berguna' tapi 'siapa yang jadi punya kendali & apakah itu aman bagi semua'.",hint:"Kekuatan terpusat bisa disalahgunakan, atau selalu efisien?"},
{n:70,type:"tf",micro:"Manfaat & tanggung jawab berjalan bersama",q:"Benar atau Salah: Besarnya potensi dampak sebuah inovasi tidak ada hubungannya dengan seberapa besar tanggung jawab memeriksanya.",answer:false,explain:"Sebaliknya, inovasi kecil yang dampaknya terbatas butuh sedikit pemeriksaan; inovasi yang bisa menyentuh jutaan orang menuntut kehati-hatian yang sebanding.",hint:"Dampak besar = tanggung jawab besar, atau tidak berhubungan?"},
{n:71,type:"mcq",micro:"Inovasi yang manipulatif",q:"Inovasi yang dirancang untuk membuat orang kecanduan atau mengambil keputusan yang merugikan diri mereka (demi keuntungan pembuat)...",options:["Sah-sah saja selama menguntungkan, sebab keberhasilan bisnis menunjukkan bahwa penggunanya memang menyukainya","Contoh inovasi terbaik karena berhasil membuat penggunanya terus memakai & tidak bisa berhenti memakainya","Bukan inovasi yang bertanggung jawab, meski secara bisnis 'berhasil', karena merugikan penggunanya dengan sengaja"],answer:2,explain:"Keberhasilan yang dibangun di atas kerugian pengguna yang disengaja adalah kegagalan etis, bukan inovasi yang patut ditiru.",hint:"Merugikan pengguna dengan sengaja = tidak bertanggung jawab, atau sah selama untung?"},
{n:72,type:"mcq",micro:"Menyeimbangkan banyak nilai",q:"Sebuah keputusan inovasi sering harus menyeimbangkan nilai yang bersaing (kemudahan vs privasi, kecepatan vs keselamatan, keuntungan vs keadilan). Sikap matang:",options:["Akui ketegangan itu, buat keputusan sadar tentang prioritas, & jelaskan alasannya secara terbuka","Berpura-pura bahwa semua nilai itu bisa dipenuhi secara maksimal sekaligus tanpa harus mengorbankan apa pun","Selalu utamakan satu nilai saja & abaikan semua nilai yang lain supaya keputusan tidak membingungkan"],answer:0,explain:"Keputusan yang jujur mengakui trade-off & bisa dipertanggungjawabkan, bukan menyembunyikan bahwa sesuatu dikorbankan.",hint:"Akui ketegangan & putuskan sadar, atau pura-pura semua terpenuhi?"},
{n:73,type:"mcq",micro:"Inovasi & rasa cukup",q:"Kapan menambahkan lebih banyak teknologi atau fitur pada sebuah solusi menjadi tidak bertanggung jawab?",options:["Hanya kalau pengguna sudah mengeluh karena fitur yang ada kurang banyak, baru boleh ada tambahan fitur lagi pada solusinya, dan hanya itu saja","Ketika tambahan itu menambah biaya, kerumitan, konsumsi sumber daya, atau risiko tanpa manfaat nyata yang sepadan bagi pengguna","Tidak pernah tidak bertanggung jawab, sebab teknologi dan fitur yang lebih banyak pada sebuah solusi selalu lebih baik bagi semua pengguna"],answer:1,explain:"Menahan diri dari menambah yang tidak perlu adalah bagian dari desain yang bertanggung jawab, terutama untuk dampak lingkungan & kemudahan.",hint:"Saat menambah tanpa manfaat sepadan, atau lebih banyak selalu lebih baik?"},
{n:74,type:"mcq",micro:"Tanggung jawab bersama",q:"Tanggung jawab atas dampak sebuah inovasi biasanya dipegang oleh...",options:["Hanya satu orang","Tidak ada, dampak 'terjadi begitu saja'","Banyak pihak: perancang, pembuat, yang mendanai, yang mengatur, & yang memakai, dengan peran berbeda"],answer:2,explain:"Rantai tanggung jawab membentang. Tiap pihak punya peran: merancang aman, mengatur batas, memakai dengan bijak. Tidak ada yang sepenuhnya lepas.",hint:"Banyak pihak dengan peran berbeda, atau satu orang / tidak ada?"},
{n:75,type:"order",micro:"Menghadapi dilema inovasi",q:"Urutkan langkah menghadapi dilema 'inovasi ini bermanfaat besar tapi berisiko serius'.",items:["Perjelas manfaatnya (untuk siapa, seberapa besar) & risikonya (untuk siapa, seberapa mungkin & parah)","Cari cara mengurangi atau menghilangkan risiko lewat desain, batasan, atau skala","Bila risiko serius tersisa, libatkan pihak terdampak & pihak yang lebih luas dalam keputusan","Putuskan: lanjut dengan pengaman, tunda sampai risiko bisa dikurangi, atau tidak dilanjutkan, & catat alasannya"],answer:[0,1,2,3],explain:"Perjelas dua sisi → kurangi risiko → libatkan yang terdampak untuk risiko sisa → putuskan & catat. Keputusan besar tidak dibuat sendirian & diam-diam.",hint:"Melibatkan pihak terdampak sebelum atau sesudah mencoba mengurangi risiko?"},
{n:76,type:"tf",micro:"Inovasi kecil pun perlu dipikirkan",q:"Benar atau Salah: Bahkan inovasi kecil di kelas atau keluarga (aturan baru, cara baru berbagi tugas) layak dipikirkan dampaknya pada semua yang terlibat sebelum diterapkan.",answer:true,explain:"Skalanya berbeda, tapi prinsipnya sama: memeriksa 'siapa terpengaruh & bagaimana' membuat perubahan kecil pun lebih adil & lebih diterima.",hint:"Inovasi kecil pun layak dipikirkan, atau hanya yang besar?"},
{n:77,type:"mcq",micro:"Kejujuran tentang kegagalan",q:"Kalau sebuah inovasi ternyata tidak memberi manfaat yang diharapkan, sikap bertanggung jawab:",options:["Akui secara terbuka, hentikan bila membebani orang tanpa manfaat, & bagikan pelajarannya","Terus jalankan agar tidak terlihat gagal","Sembunyikan datanya"],answer:0,explain:"Mempertahankan inovasi yang tidak berguna hanya demi gengsi membebani pengguna & sumber daya. Mengakui & menghentikan adalah tanggung jawab.",hint:"Akui & hentikan bila perlu, atau pertahankan demi gengsi?"},
{n:78,type:"mcq",micro:"Menilai inovasi orang lain",q:"Saat menilai apakah sebuah inovasi (buatan orang lain) bertanggung jawab, pertanyaan kunci:",options:["Apakah inovasi itu dibuat oleh orang yang sangat terkenal, dipuji banyak orang di media massa, dan sudah memenangkan banyak penghargaan?","Siapa yang terbantu & siapa yang dirugikan? Apakah pembuatnya jujur soal batasan & dampak? Apakah ada pengaman & saluran keluhan?","Apakah inovasi itu terlihat modern, mahal, dan canggih sehingga mampu menarik perhatian banyak orang dalam waktu yang sangat singkat?"],answer:1,explain:"Menilai inovasi berarti melihat dampaknya pada semua pihak, kejujuran pembuatnya, & apakah ada mekanisme perlindungan, bukan penampilannya.",hint:"Dampak, kejujuran, pengaman, atau penampilan & ketenaran?"},
{n:79,type:"mcq",micro:"Inovasi sebagai warga",q:"Sebagai orang yang memakai & terpengaruh inovasi (bukan pembuatnya), tanggung jawab kita meliputi...",options:["Menerima apa pun yang baru tanpa berpikir panjang, sebab menolak berarti kita ketinggalan zaman","Menolak semua hal baru dari awal, sebab inovasi hanya akan membawa masalah dan merusak kebiasaan baik","Memakai dengan bijak, menyuarakan kekhawatiran, mendukung aturan yang adil, & tidak asal mengikuti hanya karena baru"],answer:2,explain:"Inovasi yang bertanggung jawab butuh masyarakat yang kritis & terlibat, bukan hanya pembuat yang baik. Kita punya peran.",hint:"Memakai bijak & bersuara, atau menerima tanpa berpikir / menolak semua?"},
{n:80,type:"open",micro:"Dilema inovasi",q:"Pilih atau bayangkan satu inovasi nyata yang punya manfaat besar & juga risiko serius (mis. kecerdasan buatan untuk membantu belajar, drone pengantar barang, aplikasi yang membuat belajar jadi permainan). Tulis analisis: (a) manfaat utama & untuk siapa, (b) 2-3 risiko serius & siapa yang menanggungnya, (c) cara mengurangi tiap risiko lewat desain, aturan, atau cara pemakaian, (d) risiko yang tetap ada, (e) posisimu: apakah & bagaimana inovasi ini sebaiknya dikembangkan, dengan syarat apa.",explain:"Jawaban baik: manfaat yang jelas & menyebut siapa yang paling terbantu, 2-3 risiko serius yang berbeda dengan penjelasan siapa yang menanggung (bukan hanya 'buruk'), cara mengurangi tiap risiko yang konkret & melibatkan desain + aturan + cara pemakaian (bukan hanya satu), pengakuan jujur atas risiko yang tersisa, & posisi yang jelas dengan syarat-syarat, bukan sekadar 'ada baik ada buruk'.",hint:"Bagian (e) harus mengambil sikap. 'Layak dengan syarat X, Y, Z' atau 'sebaiknya tidak karena...' lebih baik daripada menggantung.",sample:"Inovasi: asisten belajar berbasis kecerdasan buatan yang bisa menjawab pertanyaan & menjelaskan materi kapan saja. (a) Manfaat utama: siswa bisa mendapat penjelasan tambahan di luar jam sekolah, terutama yang tidak punya akses les atau orang tua yang bisa membantu, ini bisa mempersempit kesenjangan. (b) Risiko serius: (1) siswa memakainya untuk mengerjakan tugas sepenuhnya tanpa belajar, sehingga keterampilan berpikir & menulis tidak berkembang, yang menanggung, siswa itu sendiri di masa depan & juga guru yang jadi salah menilai kemampuan kelas; (2) jawaban AI bisa salah atau bias tapi terdengar meyakinkan, siswa yang belum bisa memeriksa jadi mempelajari hal keliru; (3) kesenjangan justru melebar kalau hanya siswa dengan HP & kuota bagus yang bisa memakainya, sementara yang paling butuh malah tidak punya akses. (c) Mengurangi risiko: (1) rancang agar mode 'bantu belajar' memberi petunjuk & pertanyaan balik, bukan jawaban jadi; guru memberi tugas yang menilai proses (draf, penjelasan lisan), bukan hanya hasil; ajarkan siswa kapan pantas & tidak pantas memakainya. (2) selalu tampilkan pengingat 'periksa ini, aku bisa salah', ajarkan cara memverifikasi ke sumber lain, & guru membahas contoh jawaban AI yang keliru di kelas. (3) sediakan akses lewat komputer sekolah/perpustakaan & jam khusus, jadikan ada versi yang ringan kuota, & prioritaskan siswa yang paling butuh. (d) Risiko yang tetap ada: sebagian siswa akan tetap memakainya untuk menyontek meski ada pengaman, & tidak semua kesalahan jawaban bisa ditangkap. (e) Posisiku: layak dikembangkan, tapi HANYA sebagai alat bantu yang dirancang untuk mendorong berpikir (bukan memberi jawaban jadi), disertai pendidikan cara memakainya dengan jujur & kritis, akses yang diupayakan adil, & pemantauan oleh sekolah terhadap dampaknya pada cara belajar siswa. Kalau ternyata membuat sebagian besar siswa berhenti berusaha berpikir sendiri, penggunaannya perlu dibatasi atau diubah."},
{n:81,type:"mcq",micro:"Skenario: fitur menarik tapi merugikan",q:"Timmu ingin menambahkan notifikasi yang sangat sering agar aplikasi kelas 'lebih aktif dipakai', tapi kamu tahu itu akan mengganggu waktu istirahat & tidur siswa. Sikap:",options:["Sampaikan kekhawatiran dengan data/alasan, usulkan alternatif (notifikasi terjadwal & bisa dimatikan), & bela kepentingan pengguna","Ikut saja pada usulan tim karena mayoritas anggota menginginkannya dan kamu tidak ingin berbeda sendiri atau dianggap menghambat pekerjaan","Buat notifikasinya lebih sering lagi supaya aplikasi terlihat 'lebih aktif dipakai' dan jumlah pengguna harian naik di mata guru"],answer:0,explain:"Inovasi yang bertanggung jawab menempatkan kesejahteraan pengguna di atas metrik 'keaktifan' yang dikejar demi kepentingan pembuat.",hint:"Bela kepentingan pengguna & usulkan alternatif, atau ikut demi metrik?"},
{n:82,type:"mcq",micro:"Skenario: inovasi bagus, akses timpang",q:"Solusi digitalmu sangat membantu, tapi 30% siswa di sekolahmu tidak punya perangkat. Sikap bertanggung jawab:",options:["Tunda seluruh proyek tanpa batas waktu sampai semua siswa di sekolah memiliki perangkat pribadi masing-masing, baru kemudian dijalankan","Sediakan jalur setara yang tidak butuh perangkat pribadi (versi cetak, komputer sekolah, bantuan petugas) sejak awal, bukan setelah dikeluhkan","Jalankan saja proyeknya seperti rencana, sedangkan siswa yang tidak punya perangkat adalah urusan mereka sendiri untuk mencari jalan keluarnya"],answer:1,explain:"Inovasi yang hanya melayani yang sudah beruntung memperlebar kesenjangan. Menyediakan akses setara adalah bagian dari desain, bukan tambahan.",hint:"Sediakan jalur setara sejak awal, atau abaikan yang tak punya akses?"},
{n:83,type:"mcq",micro:"Skenario: dampak buruk muncul setelah rilis",q:"Sebulan setelah program 'papan peringkat kebaikan' berjalan, beberapa siswa dilaporkan dijauhi karena poinnya rendah. Langkah:",options:["Lanjutkan program itu karena 'kebanyakan siswa menyukainya' dan beberapa laporan itu mungkin dibesar-besarkan","Salahkan siswa yang menjauhi temannya dan abaikan bentuk programnya karena menurutmu desainnya sudah baik","Hentikan atau ubah bentuk program segera, dengarkan siswa yang terdampak, & perbaiki desainnya (mis. hapus peringkat individual)"],answer:2,explain:"Ketika inovasi menimbulkan kerugian nyata pada sebagian orang, menanggapi cepat & memperbaiki desain lebih penting daripada mempertahankan program.",hint:"Hentikan/ubah & perbaiki desain, atau lanjut karena mayoritas suka?"},
{n:84,type:"mcq",micro:"Skenario: klaim yang dilebih-lebihkan",q:"Untuk menarik minat, kelompokmu ingin mengklaim solusi kalian 'menghilangkan sepenuhnya' sebuah masalah, padahal hanya menguranginya. Sikap:",options:["Sampaikan klaim yang akurat ('mengurangi secara signifikan, berdasarkan uji kami ...') meski kurang mengesankan","Pakai klaim yang berlebihan agar lebih menarik perhatian juri dan penonton walau tidak sepenuhnya benar","Tidak menyebut hasilnya sama sekali supaya tidak ada yang bisa menyalahkan klaim kelompok kalian nantinya"],answer:0,explain:"Klaim jujur membangun kepercayaan jangka panjang; klaim berlebihan menipu pengguna & runtuh saat diuji.",hint:"Klaim akurat meski kurang wah, atau dilebih-lebihkan?"},
{n:85,type:"tf",micro:"Inovasi yang baik memberdayakan",q:"Benar atau Salah: Inovasi yang bertanggung jawab tidak perlu peduli apakah pengguna jadi lebih bergantung & kurang paham, selama alatnya berguna.",answer:false,explain:"Sebaliknya, tujuan yang sehat adalah memperkuat orang, memberi mereka lebih banyak kemampuan, pilihan, & pemahaman. Inovasi yang menjebak atau membuat orang tak berdaya tanpanya patut dipertanyakan.",hint:"Memberdayakan & memberi pemahaman, atau menjebak & membuat tak berdaya?"},
{n:86,type:"mcq",micro:"Skenario: tekanan tenggat vs pemeriksaan keselamatan",q:"Tenggat lomba besok, tapi kamu belum sempat memeriksa apakah prototipe alatmu aman dipegang anak kecil. Sikap:",options:["Sembunyikan bagian alat yang mungkin berbahaya itu supaya juri tidak mengurangi nilai kelompokmu, lalu perbaiki setelah lomba selesai","Pemeriksaan keselamatan tidak boleh dilewati; sampaikan ke juri bahwa alat belum diuji keamanannya & tidak untuk dipegang anak kecil dulu","Biarkan saja dan tetap pamerkan seperti biasa, sebab kemungkinan besar alatnya aman untuk dipegang anak kecil walau belum pernah diperiksa"],answer:1,explain:"Beberapa pemeriksaan (keselamatan, terutama untuk yang rentan) tidak boleh dikorbankan demi tenggat. Kejujuran tentang status uji melindungi orang.",hint:"Keselamatan tidak boleh dilewati & jujur soal status, atau abaikan demi tenggat?"},
{n:87,type:"mcq",micro:"Skenario: inovasi menggeser peran orang",q:"Idemu 'papan informasi otomatis' akan menggantikan tugas seorang petugas yang selama ini menuliskannya. Sikap bertanggung jawab:",options:["Terapkan secara diam-diam saja lalu biarkan pihak sekolah yang memberi tahu petugas itu belakangan","Anggap itu bukan urusanmu, sebab tugas kelompokmu hanya membuat papan informasinya, bukan memikirkan petugas","Bicarakan lebih dulu dengan petugas & sekolah; cari apakah perannya bisa bergeser ke hal lain yang berguna, bukan sekadar dihapus"],answer:2,explain:"Inovasi yang menyentuh mata pencaharian atau peran orang menuntut komunikasi & memikirkan peralihan, bukan penggusuran diam-diam.",hint:"Bicarakan & pikirkan peralihan peran, atau terapkan diam-diam?"},
{n:88,type:"mcq",micro:"Skenario: data yang dikumpulkan lebih dari perlu",q:"Aplikasi buatan kelompokmu meminta akses ke lokasi, kontak, & kamera, padahal fungsinya hanya mencatat tugas. Sikap:",options:["Minta hanya izin yang benar-benar diperlukan fungsinya, & jelaskan untuk apa tiap izin","Minta semua izin yang tersedia 'untuk berjaga-jaga' kalau suatu saat fitur baru ingin ditambahkan nanti","Minta izin secara diam-diam tanpa penjelasan apa pun supaya pengguna tidak sempat menolak atau bertanya"],answer:0,explain:"Mengumpulkan data seperlunya & transparan adalah dasar menghormati privasi. 'Berjaga-jaga' bukan alasan yang sah.",hint:"Seperlunya & dijelaskan, atau semua untuk berjaga-jaga?"},
{n:89,type:"mcq",micro:"Skenario: menilai inovasi yang viral",q:"Sebuah aplikasi sangat populer di sekolahmu, semua memakainya. Sebelum ikut, pertimbangan yang bertanggung jawab:",options:["Tolak saja hanya karena aplikasi itu populer, sebab sesuatu yang dipakai semua orang pasti kurang istimewa dan tidak layak dipercaya","Cek: data apa yang diambil, siapa pembuatnya, apa dampaknya pada waktu & perasaan penggunanya, & apakah aman, popularitas bukan jaminan","Ikut saja karena semua teman memakainya, jadi tentu sudah aman & tidak perlu diperiksa lagi oleh siapa pun sebelum kita mencobanya"],answer:1,explain:"'Semua memakainya' bukan bukti bahwa sesuatu aman atau bermanfaat. Menilai sendiri dengan kriteria yang jelas adalah tanggung jawab sebagai pengguna.",hint:"Nilai sendiri dengan kriteria, atau ikut / tolak karena populer?"},
{n:90,type:"order",micro:"Proyek: inovasi bertanggung jawab",q:"Urutkan langkah mengembangkan sebuah inovasi kecil secara bertanggung jawab.",items:["Pahami masalah & pengguna nyata; pastikan masalahnya penting","Rancang solusi & petakan pemangku kepentingan serta dampak positif/negatif","Bangun pengaman untuk risiko utama; uji di skala kecil & pantau dampak pada semua pihak","Berdasar hasil: perbaiki, luncurkan lebih luas dengan saluran keluhan, atau hentikan; catat pelajaran"],answer:[0,1,2,3],explain:"Pahami → rancang & petakan dampak → pengaman & uji kecil → putuskan & pantau terus. Dampak dipikirkan di sepanjang proses, bukan di akhir.",hint:"Membangun pengaman sebelum atau sesudah memetakan dampak?"},
{n:91,type:"mcq",micro:"Skenario: manfaat besar, satu kelompok dirugikan",q:"Inovasimu jelas membantu 90% siswa tapi membuat 10% (yang punya kondisi tertentu) lebih sulit. Kamu sudah coba kurangi & masih tersisa. Sikap:",options:["Abaikan 10% siswa itu karena mayoritas sudah terbantu & tidak mungkin menyenangkan semua orang sekaligus","Batalkan seluruh inovasi itu karena inovasi yang menyulitkan satu orang saja tidak boleh dipakai sama sekali","Nyatakan trade-off ini terbuka ke semua, sediakan bantuan khusus & jalur alternatif untuk 10% itu, & terus cari cara memperbaiki"],answer:2,explain:"Tanggung jawab tidak selalu berarti solusi sempurna untuk semua, tapi berarti tidak menyembunyikan kerugian & sungguh-sungguh membantu yang menanggungnya.",hint:"Terbuka + bantuan khusus + terus perbaiki, atau abaikan / batalkan?"},
{n:92,type:"tf",micro:"Inovasi & kerendahan hati",q:"Benar atau Salah: Sikap yang menyertai inovasi yang bertanggung jawab adalah kerendahan hati, mengakui bahwa kita mungkin tidak melihat semua dampak, & karena itu memantau, mendengarkan, & siap memperbaiki.",answer:true,explain:"Tidak ada yang bisa memperkirakan semua konsekuensi. Kerendahan hati membuat kita tetap waspada & responsif setelah peluncuran.",hint:"Kerendahan hati & terus memantau, atau yakin sudah memikirkan semua?"},
{n:93,type:"mcq",micro:"Skenario: idemu ditolak karena risiko",q:"Guru pembimbing menolak idemu karena satu risiko serius. Respons yang matang:",options:["Tanyakan risiko persisnya, coba rancang ulang untuk menghilangkannya, & ajukan lagi, atau terima bila memang tidak bisa dikurangi","Merasa kesal & menganggap guru hanya menghambat idemu yang sebenarnya sudah bagus, lalu berhenti mengusulkan ide kepada beliau selamanya","Jalankan saja secara diam-diam tanpa izin guru, lalu tunjukkan hasilnya setelah semua orang terkesan sehingga guru tidak jadi melarang"],answer:0,explain:"Risiko yang ditunjukkan adalah bahan untuk memperbaiki ide, bukan vonis final. Kadang setelah dirancang ulang, ide bisa jalan; kadang memang sebaiknya tidak.",hint:"Rancang ulang & ajukan lagi / terima, atau kesal / diam-diam?"},
{n:94,type:"mcq",micro:"Skenario: inovasi yang menyenangkan tapi boros",q:"Idemu untuk acara sekolah keren tapi menghasilkan banyak sampah sekali pakai. Sikap bertanggung jawab:",options:["Batalkan acara itu sepenuhnya, sebab acara yang menghasilkan sampah tidak boleh diadakan dalam bentuk apa pun","Cari versi yang memberi kesan serupa dengan bahan yang bisa dipakai ulang atau terurai, atau kurangi skalanya","Jalankan saja acaranya seperti rencana semula, urusan sampah bisa dipikirkan nanti setelah acara selesai"],answer:1,explain:"Dampak lingkungan adalah bagian dari 'biaya' inovasi. Mencari versi yang sama menyenangkan tapi lebih ringan jejaknya adalah tanggung jawab.",hint:"Cari versi lebih ramah lingkungan, atau abaikan sampah / batalkan?"},
{n:95,type:"tf",micro:"Inovasi terbaik terasa membantu, bukan memaksa",q:"Benar atau Salah: Inovasi yang bertanggung jawab membuat pilihan yang baik menjadi lebih mudah & jelas, tanpa menjebak, menekan diam-diam, atau menghilangkan kebebasan orang.",answer:true,explain:"Perbedaan antara 'membantu orang memilih baik' & 'memanipulasi orang' ada pada transparansi & penghormatan pada kebebasan mereka.",hint:"Memudahkan pilihan baik tanpa menjebak, atau menekan diam-diam?"},
{n:96,type:"mcq",micro:"Skenario: menimbang berhenti",q:"Setelah beberapa bulan, datamu menunjukkan inovasimu tidak mengurangi masalah yang dituju & sedikit membebani pengguna. Sikap:",options:["Pertahankan inovasinya supaya kelompok tidak terlihat gagal di depan guru, teman, dan orang tua","Ubah cara mengukurnya agar hasilnya terlihat berhasil walau kenyataannya masalah itu tidak berkurang","Akui secara terbuka, hentikan atau ubah drastis, & bagikan apa yang dipelajari agar orang lain tidak mengulang"],answer:2,explain:"Menghentikan sesuatu yang tidak berhasil, dengan jujur, adalah keputusan yang bertanggung jawab, bukan kegagalan yang memalukan.",hint:"Akui & hentikan/ubah, atau pertahankan demi gengsi / manipulasi data?"},
{n:97,type:"mcq",micro:"Menilai kualitas caramu berinovasi",q:"Tanda kamu berinovasi secara bertanggung jawab:",options:["Kamu mulai dari kebutuhan nyata, memetakan siapa terdampak, memikirkan penyalahgunaan & yang tersisih, jujur soal batasan, & memantau dampak setelah peluncuran","Kamu membuat sesuatu yang baru & sangat mengesankan secepat mungkin, lalu memikirkan dampak buruknya nanti saja kalau memang ada yang melaporkan","Kamu tidak pernah memikirkan dampak apa pun di luar pengguna langsung karena itu bukan tanggung jawabmu dan hanya akan memperlambat pekerjaan"],answer:0,explain:"Prosesnya: kebutuhan nyata → peta dampak → pengaman & inklusi → kejujuran → pemantauan. Bukan sekadar 'baru & cepat'.",hint:"Kebutuhan-dampak-pengaman-jujur-pantau, atau baru & cepat?"},
{n:98,type:"mcq",micro:"Inovasi & masyarakat",q:"Selain pembuat, apa yang membantu inovasi di masyarakat tetap bertanggung jawab?",options:["Membiarkan pasar memutuskan segalanya tanpa aturan, sebab pasar pasti menyingkirkan inovasi yang buruk","Aturan yang adil, media & warga yang kritis, pendidikan yang mengajarkan menilai teknologi, & pengguna yang bijak","Hanya kebaikan hati para pembuat inovasi, sebab aturan dan pengawasan justru akan menghambat kemajuan"],answer:1,explain:"Inovasi yang bertanggung jawab adalah tanggung jawab bersama: pembuat yang baik, aturan yang adil, & masyarakat yang sadar & terlibat.",hint:"Aturan + warga kritis + pendidikan + pengguna bijak, atau hanya kebaikan pembuat?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'inovasi yang bermanfaat & bertanggung jawab':",options:["Ciptakan sesuatu yang baru & sangat mengesankan secepat mungkin untuk menarik banyak orang, lalu pikirkan dampaknya belakangan jika ada yang memprotes atau melaporkan masalah","Hindari membuat apa pun yang mengandung risiko sedikit pun, sebab inovasi yang aman sepenuhnya adalah satu-satunya yang boleh dibuat supaya tidak ada pihak yang merasa dirugikan","Ciptakan sesuatu yang baru & benar-benar membantu kebutuhan nyata orang, sambil memetakan & mengelola dampaknya pada semua pihak & lingkungan, jujur soal batasan, & terus memantau setelah dipakai"],answer:2,explain:"Baru + bermanfaat nyata + dampak dikelola + jujur + dipantau. Berani mencoba hal berarti, sambil serius pada tanggung jawabnya.",hint:"Bermanfaat nyata + dampak dikelola + jujur + dipantau, atau baru & mengesankan saja?"},
{n:100,type:"open",micro:"Kapstone: piagam inovasi pribadi",q:"Tulis 'piagam inovasi' pribadimu, aturan yang akan kamu pegang setiap kali membuat atau memperkenalkan sesuatu yang baru untuk dipakai orang lain. Sertakan: (a) 3-5 prinsip (mis. tentang memahami kebutuhan, memetakan dampak, kejujuran, inklusi, pemantauan), (b) untuk tiap prinsip, satu tindakan konkret yang menunjukkannya, (c) satu 'garis merah', hal yang tidak akan kamu langgar meski ada tekanan, (d) bagaimana kamu akan menagih diri sendiri agar benar-benar mengikuti piagam ini.",explain:"Jawaban baik: 3-5 prinsip yang mencakup memahami kebutuhan, memetakan dampak, kejujuran, inklusi/akses, & pemantauan pasca-rilis; tiap prinsip dipasangkan dengan tindakan konkret yang bisa benar-benar dilakukan (bukan sikap umum); satu garis merah yang jelas & spesifik tentang hal yang tidak akan dilanggar meski ada tekanan; & mekanisme akuntabilitas yang nyata (menulis, meninjau, atau meminta orang lain memeriksa), bukan sekadar 'aku akan berusaha ingat'.",hint:"Bagian (c) & (d) yang membedakan piagam yang serius, garis merahmu harus spesifik & disebut bersama tekanan yang mungkin datang, dan cara menagih diri harus melibatkan tindakan atau orang lain, bukan hanya niat.",sample:"(a) & (b) Prinsip & tindakannya: (1) 'Mulai dari kebutuhan nyata, bukan dari ide yang ingin kupakai', tindakan, sebelum membuat apa pun, aku bicara dengan minimal 3 calon pengguna & menuliskan masalah mereka dengan kata-kata mereka. (2) 'Petakan siapa yang terdampak, termasuk yang tidak memakainya', tindakan, membuat daftar pemangku kepentingan & menulis satu dampak positif & satu negatif untuk tiap pihak sebelum melanjutkan. (3) 'Jujur soal apa yang bisa & tidak bisa dilakukan', tindakan, setiap kali memperkenalkan sesuatu, aku menyebut minimal satu batasannya secara terbuka & tidak memakai klaim yang belum kubuktikan. (4) 'Rancang agar bisa diakses sebanyak mungkin orang', tindakan, memeriksa apakah ada yang tidak bisa memakai karena alat, biaya, bahasa, atau kemampuan, & menyiapkan jalur setara sebelum meluncurkan. (5) 'Tanggung jawabku tidak berhenti saat rilis', tindakan, menyediakan cara orang melapor masalah & meninjau dampak setelah 2-4 minggu, siap mengubah atau menghentikan. (c) Garis merah: aku tidak akan membuat atau menambahkan sesuatu yang kutahu dirancang untuk menipu, menjebak, atau merugikan penggunanya demi keuntungan pembuat, meski disuruh atau meski 'semua orang melakukannya'. Aku juga tidak akan melewati pemeriksaan keselamatan untuk hal yang dipakai anak kecil atau orang rentan demi tenggat. (d) Menagih diri sendiri: aku menempel piagam ini di buku catatan proyek & di awal tiap proyek baru aku menuliskan 'bagaimana proyek ini memenuhi 5 prinsip', lalu di akhir aku menilai lagi dengan jujur; aku juga meminta satu teman untuk menjadi 'pemeriksa' yang boleh menanyakan 'sudah kamu cek dampaknya ke siapa?' kapan saja."},
];
